let charts = {};
        function loadDemo() {
            // Generate fake history artifact
            const history = [];
            const domains = ['google.com', 'youtube.com', 'github.com', 'stackoverflow.com', 'twitter.com', 'reddit.com', 'news.ycombinator.com', 'linkedin.com', 'amazon.com'];
            const now = Date.now();
            for (let i = 0; i < 3000; i++) {
                const dom = domains[Math.floor(Math.random() * domains.length)];
                const time = now - (Math.random() * 2592000000); // Random within 30 days
                history.push({
                    url: `https://${dom}/artifact/${i}`,
                    visitTime: time
                });
            }
            processData(history);
        }
        function handleFile(input) {
            if (input.files && input.files[0]) {
                const reader = new FileReader();
                document.getElementById('loading').classList.remove('hidden');
                document.getElementById('upload-view').classList.add('hidden');
                reader.onload = (e) => {
                    try {
                        const json = JSON.parse(e.target.result);
                        // Support standard Chrome Export format
                        const data = json["Browser History"] || json;
                        const history = data.map(item => ({
                            url: item.url,
                            visitTime: item.time_usec ? item.time_usec / 1000 : item.visitTime
                        }));
                        processData(history);
                    } catch (err) {
                        alert("Error parsing JSON. Ensure it is a valid Chrome/Firefox history export.");
                        resetTool();
                    }
                };
                reader.readAsText(input.files[0]);
            }
        }
        function processData(history) {
            const total = history.length;
            const domains = {};
            const hourly = new Array(24).fill(0);
            const daily = {};
            history.forEach(item => {
                try {
                    const url = new URL(item.url);
                    const dom = url.hostname.replace('www.', '');
                    domains[dom] = (domains[dom] || 0) + 1;
                    const date = new Date(item.visitTime);
                    hourly[date.getHours()]++;
                    const day = date.toISOString().split('T')[0];
                    daily[day] = (daily[day] || 0) + 1;
                } catch (e) { }
            });
            const sortedDomains = Object.entries(domains).sort((a, b) => b[1] - a[1]);
            const busiestDay = Object.entries(daily).sort((a, b) => b[1] - a[1])[0];
            const peakHour = hourly.indexOf(Math.max(...hourly));
            document.getElementById('total-visits').innerText = total.toLocaleString();
            document.getElementById('unique-sites').innerText = Object.keys(domains).length.toLocaleString();
            document.getElementById('busiest-day').innerText = busiestDay ? busiestDay[0] : '--';
            document.getElementById('peak-hour').innerText = `${peakHour}:00`;
            renderCharts(hourly, sortedDomains.slice(0, 5));
            renderList(sortedDomains.slice(0, 15), total);
            document.getElementById('loading').classList.add('hidden');
            document.getElementById('dashboard').classList.remove('hidden');
        }
        function renderCharts(hourly, topDomains) {
            if (charts.h) charts.h.destroy();
            if (charts.d) charts.d.destroy();
            const ctxH = document.getElementById('hourlyChart').getContext('2d');
            charts.h = new Chart(ctxH, {
                type: 'bar',
                data: {
                    labels: [...Array(24).keys()].map(h => `${h}:00`),
                    datasets: [{
                        label: 'Visits',
                        data: hourly,
                        backgroundColor: '#3b82f6',
                        borderRadius: 4
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { display: false } },
                    scales: {
                        x: { grid: { display: false }, ticks: { font: { size: 9, family: 'JetBrains Mono' } } },
                        y: { grid: { color: '#f1f5f9' }, ticks: { display: false } }
                    }
                }
            });
            const ctxD = document.getElementById('domainChart').getContext('2d');
            charts.d = new Chart(ctxD, {
                type: 'doughnut',
                data: {
                    labels: topDomains.map(d => d[0]),
                    datasets: [{
                        data: topDomains.map(d => d[1]),
                        backgroundColor: ['#3b82f6', '#06b6d4', '#10b981', '#f59e0b', '#ef4444'],
                        borderWidth: 0,
                        hoverOffset: 15
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { position: 'bottom', labels: { boxWidth: 10, font: { weight: 'bold', size: 10 } } } },
                    cutout: '65%'
                }
            });
        }
        function renderList(domains, total) {
            const container = document.getElementById('top-sites-list');
            container.innerHTML = '';
            domains.forEach(([domain, count], index) => {
                const pct = Math.round((count / total) * 100);
                container.innerHTML += `
                    <div class="site-row group">
                        <div class="site-bar-bg" style="width: ${pct * 2}%"></div>
                        <div class="relative z-10 flex items-center gap-3">
                            <span class="text-slate-400 text-xs font-mono font-black w-6">#${index + 1}</span>
                            <span class="font-black text-slate-800 text-sm truncate max-w-[200px] uppercase tracking-tighter">${domain}</span>
                        </div>
                        <div class="relative z-10 text-xs font-black text-slate-500 font-mono">
                            ${count.toLocaleString()} <span class="text-[9px] font-normal text-slate-400 uppercase">Visits</span>
                        </div>
                    </div>
                `;
            });
        }
        function resetTool() {
            document.getElementById('dashboard').classList.add('hidden');
            document.getElementById('upload-view').classList.remove('hidden');
            document.getElementById('file-input').value = '';
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }
        // --- SCROLL LOGIC ---
